package com.bocsoft.sqleditor.export;
import com.bocsoft.sqleditor.config.SqlEditorProperties;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.List;import org.springframework.stereotype.Component;
@Component public class CsvEncoder {private static final byte[]BOM={(byte)0xef,(byte)0xbb,(byte)0xbf};private final boolean protect,nullLiteral;public CsvEncoder(SqlEditorProperties p){protect=p.getExport().isFormulaProtection();nullLiteral=p.getExport().isNullLiteral();}public void bom(OutputStream out)throws IOException{out.write(BOM);}public long record(OutputStream out,List<?>values)throws IOException{StringBuilder line=new StringBuilder();for(int i=0;i<values.size();i++){if(i>0)line.append(',');line.append(field(values.get(i)));}line.append("\r\n");byte[]b=line.toString().getBytes(StandardCharsets.UTF_8);out.write(b);return b.length;}public String field(Object value){if(value==null)return nullLiteral?"NULL":"";String s=String.valueOf(value);if(protect&&!s.isEmpty()&&"=+-@".indexOf(s.charAt(0))>=0)s="'"+s;boolean quote=s.indexOf(',')>=0||s.indexOf('"')>=0||s.indexOf('\r')>=0||s.indexOf('\n')>=0;if(quote)return"\""+s.replace("\"","\"\"")+"\"";return s;}}
